import{_ as e,o,c as n,a2 as t}from"./chunks/framework.C0KMm31j.js";const s="/Nav2ArticlesSite/article-assets/2026-08-04/navigation2_overview_01_stack_to_task_platform.png",i="/Nav2ArticlesSite/article-assets/2026-08-04/navigation2_overview_02_command_chain_env_model.png",r="/Nav2ArticlesSite/article-assets/2026-08-04/navigation2_overview_03_task_hierarchy_recovery.png",l="/Nav2ArticlesSite/article-assets/2026-08-04/navigation2_overview_04_action_data_flow.png",p="/Nav2ArticlesSite/article-assets/2026-08-04/navigation2_overview_05_pdf_to_current_nav2.png",c="/Nav2ArticlesSite/article-assets/2026-08-04/navigation2_overview_06_benefits_and_boundaries.png",g=JSON.parse('{"title":"Nav2 为什么要把导航拆成任务？拆解 Navigation 2 Overview 的任务架构、环境模型与 Behavior Tree","description":"导航系统真正难的地方，往往不是把 A、DWA 或某个控制器跑起来，而是让一套系统能够持续适应不同的地图、机器人、任务、部署方式和故障场景。2018 年的 Navigation2Overview.pdf 正是在回答这个问题：Nav2 是否应该只是“规划器加控制器”，还是应该成为一套可组合的机器人任务执","frontmatter":{"title":"Nav2 为什么要把导航拆成任务？拆解 Navigation 2 Overview 的任务架构、环境模型与 Behavior Tree","description":"导航系统真正难的地方，往往不是把 A、DWA 或某个控制器跑起来，而是让一套系统能够持续适应不同的地图、机器人、任务、部署方式和故障场景。2018 年的 Navigation2Overview.pdf 正是在回答这个问题：Nav2 是否应该只是“规划器加控制器”，还是应该成为一套可组合的机器人任务执","date":"2026-08-04","section":"一 · 架构与启动","readingTime":15,"source":"2026-08-04/navigation2_overview_design_analysis.md","status":"published","cover":"/article-assets/2026-08-04/navigation2_overview_01_stack_to_task_platform.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/navigation2-overview-design-analysis"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Nav2 为什么要把导航拆成任务？拆解 Navigation 2 Overview 的任务架构、环境模型与 Behavior Tree"}],["meta",{"property":"og:description","content":"导航系统真正难的地方，往往不是把 A、DWA 或某个控制器跑起来，而是让一套系统能够持续适应不同的地图、机器人、任务、部署方式和故障场景。2018 年的 Navigation2Overview.pdf 正是在回答这个问题：Nav2 是否应该只是“规划器加控制器”，还是应该成为一套可组合的机器人任务执"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/navigation2-overview-design-analysis"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-04/navigation2_overview_01_stack_to_task_platform.png"}],["meta",{"property":"article:published_time","content":"2026-08-04"}],["meta",{"name":"twitter:title","content":"Nav2 为什么要把导航拆成任务？拆解 Navigation 2 Overview 的任务架构、环境模型与 Behavior Tree"}],["meta",{"name":"twitter:description","content":"导航系统真正难的地方，往往不是把 A、DWA 或某个控制器跑起来，而是让一套系统能够持续适应不同的地图、机器人、任务、部署方式和故障场景。2018 年的 Navigation2Overview.pdf 正是在回答这个问题：Nav2 是否应该只是“规划器加控制器”，还是应该成为一套可组合的机器人任务执"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-04/navigation2_overview_01_stack_to_task_platform.png"}]],"prev":{"text":"一个底盘，三种大脑：nav2_regulated_modules 如何用 Action 与 Service 串起整套 Nav2？","link":"/nav2/nav2-regulated-modules-three-mode-interfaces-dataflow"},"next":{"text":"Dijkstra 还是 A*，一张代价地图如何长出路径？拆解 `nav2_navfn_planner` 势场搜索全数据流","link":"/nav2/nav2-navfn-full-dataflow"}},"headers":[],"relativePath":"nav2/navigation2-overview-design-analysis.md","filePath":"nav2/navigation2-overview-design-analysis.md","lastUpdated":null}'),d={name:"nav2/navigation2-overview-design-analysis.md"};function h(v,a,m,u,_,P){return o(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="nav2-为什么要把导航拆成任务-拆解-navigation-2-overview-的任务架构、环境模型与-behavior-tree" tabindex="-1">Nav2 为什么要把导航拆成任务？拆解 Navigation 2 Overview 的任务架构、环境模型与 Behavior Tree <a class="header-anchor" href="#nav2-为什么要把导航拆成任务-拆解-navigation-2-overview-的任务架构、环境模型与-behavior-tree" aria-label="Permalink to &quot;Nav2 为什么要把导航拆成任务？拆解 Navigation 2 Overview 的任务架构、环境模型与 Behavior Tree&quot;">​</a></h1><p>导航系统真正难的地方，往往不是把 A*、DWA 或某个控制器跑起来，而是让一套系统能够持续适应不同的地图、机器人、任务、部署方式和故障场景。2018 年的 <code>Navigation_2_Overview.pdf</code> 正是在回答这个问题：Nav2 是否应该只是“规划器加控制器”，还是应该成为一套可组合的机器人任务执行平台？</p><p>本文先解释这份设计稿想解决什么问题，再沿着 Command Chain、Task Hierarchy、Environmental Model、ROS Action 和 Behavior Tree 展开完整数据流，最后对照当前 checkout 中的 <code>bt_navigator</code>、<code>planner_server</code>、<code>controller_server</code>、Costmap 和组合式启动方式，区分设计愿景与现行实现。</p><h2 id="一、先定位这份-pdf-它是架构愿景-不是算法说明" tabindex="-1">一、先定位这份 PDF：它是架构愿景，不是算法说明 <a class="header-anchor" href="#一、先定位这份-pdf-它是架构愿景-不是算法说明" aria-label="Permalink to &quot;一、先定位这份 PDF：它是架构愿景，不是算法说明&quot;">​</a></h2><h3 id="_1-1-设计稿的时间和范围" tabindex="-1">1.1 设计稿的时间和范围 <a class="header-anchor" href="#_1-1-设计稿的时间和范围" aria-label="Permalink to &quot;1.1 设计稿的时间和范围&quot;">​</a></h3><p>这份 PDF 位于 <code>navigation2/doc/design/Navigation_2_Overview.pdf</code>，共 13 页，封面时间是 2018-08-02。第 11 页记录的是当时的研发状态，第 13 页的 <code>TaskServer&lt;CommandMsg, ResultMsg&gt;</code> 还是实现草图，因此阅读时必须把“设计目标”“早期实现”和“当前 Nav2”分开。</p><p>PDF 第 2 页把目标场景从二维仓库机器人扩展到带高程的搜索救援机器人、多层建筑室内机器人、校园配送机器人，甚至把无人机三维导航列为 Stretch Target。这些场景的共同点不是都使用同一种算法，而是都需要任务、环境、运动模型和执行状态之间保持清晰边界。</p><h3 id="_1-2-a-和-dwa-只是验证样例" tabindex="-1">1.2 A* 和 DWA 只是验证样例 <a class="header-anchor" href="#_1-2-a-和-dwa-只是验证样例" aria-label="Permalink to &quot;1.2 A* 和 DWA 只是验证样例&quot;">​</a></h3><p>第 10～11 页用 <code>AStar</code> 和 <code>Dwa</code> 展示从导航任务到规划、控制的调用关系，并记录了当时对 A* 和 DWA 的 ROS 2 移植工作。它们是当时用于验证架构的算法样例，不是这份设计稿最重要的结论。</p><p>真正重要的问题是：如果明天把 A* 换成 Smac，把 DWA 换成 MPPI，把差速底盘换成 Ackermann，把“导航到目标点”扩展成“取货、乘梯、对接、交付”，上层任务代码是否仍然可以保持稳定？</p><p><img src="'+s+`" alt="图 1：从固定导航栈到任务执行平台"></p><h2 id="二、设计起点-从固定导航栈转向任务执行平台" tabindex="-1">二、设计起点：从固定导航栈转向任务执行平台 <a class="header-anchor" href="#二、设计起点-从固定导航栈转向任务执行平台" aria-label="Permalink to &quot;二、设计起点：从固定导航栈转向任务执行平台&quot;">​</a></h2><h3 id="_2-1-传统耦合边界在哪里" tabindex="-1">2.1 传统耦合边界在哪里 <a class="header-anchor" href="#_2-1-传统耦合边界在哪里" aria-label="Permalink to &quot;2.1 传统耦合边界在哪里&quot;">​</a></h3><p>传统导航栈很容易形成一条过于紧密的调用链：任务逻辑直接调用规划器，规划器和控制器直接依赖某种地图表示，控制器再直接连接某一种机器人底盘。恢复行为则经常散落在这些模块内部，导致上层很难判断到底是哪一层失败。</p><p>这种结构的直接后果是，算法替换、地图替换、机器人替换和任务扩展会相互影响。一个看似只改变控制器的需求，可能需要同时修改参数、插件加载、任务状态机和异常处理。</p><h3 id="_2-2-四个核心抽象" tabindex="-1">2.2 四个核心抽象 <a class="header-anchor" href="#_2-2-四个核心抽象" aria-label="Permalink to &quot;2.2 四个核心抽象&quot;">​</a></h3><p>这份 PDF 实际上提出了四个互相配合的抽象：</p><ul><li>Task：用“导航到目标”“计算路径”“跟踪路径”“恢复”这样的业务语义组织功能。</li><li>ROS Action：用 Goal、Feedback、Result 和 Cancel 定义长时间异步任务的通信契约。</li><li>Environmental Model：把感知、预测、建图、定位等输入封装成任务需要的环境语义。</li><li>Behavior Tree：在任务变复杂时，负责组合子任务、重试、恢复、抢占和条件分支。</li></ul><p>其中 Task 是架构语义，Action 是通信边界，Plugin 是一种实现手段，Behavior Tree 是一种编排手段。把这四者混为一谈，就会误解 PDF 的设计目标。</p><h3 id="_2-3-从-算法调用-变成-任务契约" tabindex="-1">2.3 从“算法调用”变成“任务契约” <a class="header-anchor" href="#_2-3-从-算法调用-变成-任务契约" aria-label="Permalink to &quot;2.3 从“算法调用”变成“任务契约”&quot;">​</a></h3><p>设计稿希望上层只依赖稳定的任务契约：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComputePathToPose：输入起点和终点，输出 Path</span></span>
<span class="line"><span>FollowPath：输入 Path，输出执行结果</span></span>
<span class="line"><span>NavigateToPose：输入目标位姿，协调规划、控制和恢复</span></span></code></pre></div><p>上层不需要知道下层究竟使用 A*、Dijkstra、DWA、MPPI 还是其他算法。只要输入、输出、取消和失败语义稳定，内部实现就可以替换。</p><h2 id="三、两张平面-command-chain-与-environmental-model" tabindex="-1">三、两张平面：Command Chain 与 Environmental Model <a class="header-anchor" href="#三、两张平面-command-chain-与-environmental-model" aria-label="Permalink to &quot;三、两张平面：Command Chain 与 Environmental Model&quot;">​</a></h2><h3 id="_3-1-command-chain-负责-要做什么" tabindex="-1">3.1 Command Chain 负责“要做什么” <a class="header-anchor" href="#_3-1-command-chain-负责-要做什么" aria-label="Permalink to &quot;3.1 Command Chain 负责“要做什么”&quot;">​</a></h3><p>PDF 第 5～7 页的高层架构，可以理解为一条垂直的任务指挥链：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Robot Management</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Mission Planning</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Mission Execution</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Tasks</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Robot</span></span></code></pre></div><p>Robot Management 和 Mission Planning 负责产生任务计划，Mission Execution 负责执行计划，Tasks 负责把任务进一步拆成可以执行和监控的子任务，Robot 是最终动作执行者。</p><p>这条链条解决的是控制问题：当前任务是什么，应该调用哪个子任务，哪个子任务失败后应该恢复还是终止，新的 Goal 到达后是否抢占当前任务。</p><h3 id="_3-2-support-infrastructure-负责提供环境事实" tabindex="-1">3.2 Support Infrastructure 负责提供环境事实 <a class="header-anchor" href="#_3-2-support-infrastructure-负责提供环境事实" aria-label="Permalink to &quot;3.2 Support Infrastructure 负责提供环境事实&quot;">​</a></h3><p>Perception、Prediction、Mapping 和 Localization 不属于某个具体导航任务，它们是支持基础设施。它们不断产生环境信息，再由 Environmental Model 或相应的服务接口提供给任务层。</p><p>这使任务逻辑不必直接依赖某个激光雷达 Topic、某个地图文件格式或某个预测算法的内部对象。任务需要的是“当前有什么障碍”“目标可能移动到哪里”“这块区域是否安全”，而不是传感器数据在内存中具体长什么样。</p><h3 id="_3-3-environmental-model-负责抽象和封装" tabindex="-1">3.3 Environmental Model 负责抽象和封装 <a class="header-anchor" href="#_3-3-environmental-model-负责抽象和封装" aria-label="Permalink to &quot;3.3 Environmental Model 负责抽象和封装&quot;">​</a></h3><p>PDF 第 8～9 页把 Environmental Model 描述成环境知识的聚合层，同时强调两个关键词：Abstraction 和 Encapsulation。</p><p>Abstraction 表示任务看到的是高层语义，例如对象信息、对象跟踪信息、对象预测信息、安全区域和静态地图。Encapsulation 表示这些信息的内部表示可以变化，任务不需要知道它们来自 OccupancyGrid、点云、对象列表、预测轨迹还是远程服务。</p><p>这里最重要的判断是：Environmental Model 不应该被理解成一张“什么都塞进去”的巨型地图。它更像面向任务的语义访问层，负责隐藏数据来源和内部表示，同时给出稳定的查询接口。</p><p><img src="`+i+`" alt="图 2：Command Chain 与 Environmental Model 的双平面架构"></p><h2 id="四、任务层级如何组合执行" tabindex="-1">四、任务层级如何组合执行 <a class="header-anchor" href="#四、任务层级如何组合执行" aria-label="Permalink to &quot;四、任务层级如何组合执行&quot;">​</a></h2><h3 id="_4-1-task-是有生命周期的语义单元" tabindex="-1">4.1 Task 是有生命周期的语义单元 <a class="header-anchor" href="#_4-1-task-是有生命周期的语义单元" aria-label="Permalink to &quot;4.1 Task 是有生命周期的语义单元&quot;">​</a></h3><p>一个 Task 不只是一个同步函数，它通常具有 Goal、执行状态、Feedback、Result、Cancel、Failure 和 Recovery。它还可以调用其他 Task，因此可以构成父子层级。</p><p>例如 <code>NavigateToPoseTask</code> 不必亲自实现路径搜索和速度计算，它只需要协调 <code>ComputePathToPoseTask</code> 和 <code>FollowPathTask</code>，然后把子任务结果转换成自己的导航结果。</p><h3 id="_4-2-mission-到-robot-的任务树" tabindex="-1">4.2 Mission 到 Robot 的任务树 <a class="header-anchor" href="#_4-2-mission-到-robot-的任务树" aria-label="Permalink to &quot;4.2 Mission 到 Robot 的任务树&quot;">​</a></h3><p>PDF 第 10 页给出了最清晰的示意：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MissionExecutionTask</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>NavigateToPoseTask</span></span>
<span class="line"><span>        ├── ComputePathToPoseTask</span></span>
<span class="line"><span>        └── FollowPathTask</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>              Robot</span></span></code></pre></div><p><code>MissionExecutionTask</code> 的输入是 <code>MissionPlan</code>，它可以包含多个导航任务，也可以包含对接、等待、开门和乘梯等非导航任务。<code>NavigateToPoseTask</code> 接收目标位姿，先获得 Path，再把 Path 交给路径跟踪任务。</p><p>这种层级的价值在于，任务可以复用。一个“去充电桩”的任务可以复用“导航到目标点”，一个“配送到房间”的任务可以复用“取货、导航、交付、返回”这些更小的任务。</p><h3 id="_4-3-简单代码、状态机和-behavior-tree" tabindex="-1">4.3 简单代码、状态机和 Behavior Tree <a class="header-anchor" href="#_4-3-简单代码、状态机和-behavior-tree" aria-label="Permalink to &quot;4.3 简单代码、状态机和 Behavior Tree&quot;">​</a></h3><p>设计稿没有规定所有 Task 都必须使用 Behavior Tree。它给出了三种协调方式：</p><ul><li>简单任务使用手写逻辑。</li><li>中等复杂任务使用状态机。</li><li>需要条件分支、循环、恢复、并行或动态抢占时使用 Behavior Tree。</li></ul><p>Behavior Tree 的位置是任务编排器，而不是全局规划器或局部控制器。它决定何时调用规划、何时调用控制、何时执行恢复，以及何时把失败向上返回。</p><h3 id="_4-4-recovery-也是-task" tabindex="-1">4.4 Recovery 也是 Task <a class="header-anchor" href="#_4-4-recovery-也是-task" aria-label="Permalink to &quot;4.4 Recovery 也是 Task&quot;">​</a></h3><p>恢复行为被提升为正式任务后，清理 Costmap、旋转、后退、等待、重新规划就不再是某个函数内部的隐藏分支，而是可以单独配置、组合、测试和观测的节点。</p><p>这也是为什么 PDF 强调“把恢复行为作为任务或 ROS Action”：恢复过程同样需要取消、超时、反馈和最终结果。</p><p><img src="`+r+'" alt="图 3：任务层级、子任务与恢复"></p><h2 id="五、从-goal-到-cmd-vel-的数据闭环" tabindex="-1">五、从 Goal 到 cmd_vel 的数据闭环 <a class="header-anchor" href="#五、从-goal-到-cmd-vel-的数据闭环" aria-label="Permalink to &quot;五、从 Goal 到 cmd_vel 的数据闭环&quot;">​</a></h2><h3 id="_5-1-外部-goal-进入-mission-或-navigatetopose" tabindex="-1">5.1 外部 Goal 进入 Mission 或 NavigateToPose <a class="header-anchor" href="#_5-1-外部-goal-进入-mission-或-navigatetopose" aria-label="Permalink to &quot;5.1 外部 Goal 进入 Mission 或 NavigateToPose&quot;">​</a></h3><p>在 PDF 的理想链路中，外部管理器发送 <code>ExecuteMissionCommand(MissionPlan)</code>，Mission Execution 再发送 <code>NavigateToPoseCommand</code>。这说明高层任务和底层导航之间也是异步协议关系，而不是直接调用 C++ 函数。</p><p>当前 Nav2 的 <code>NavigateToPose.action</code> 仍然保留了类似的边界。它的 Goal 是 <code>geometry_msgs/PoseStamped pose</code> 和 <code>string behavior_tree</code>，Feedback 包含当前位姿、导航时间、预计剩余时间、恢复次数和剩余距离。</p><p>因此当前调用可以表达两层意图：</p><ul><li><code>pose</code> 表示机器人要去哪里。</li><li><code>behavior_tree</code> 表示这次导航应该采用哪套任务编排逻辑。</li></ul><h3 id="_5-2-computepathtopose-产生-path" tabindex="-1">5.2 ComputePathToPose 产生 Path <a class="header-anchor" href="#_5-2-computepathtopose-产生-path" aria-label="Permalink to &quot;5.2 ComputePathToPose 产生 Path&quot;">​</a></h3><p>Behavior Tree 的 <code>ComputePathToPose</code> 节点从 Blackboard 读取目标和 <code>planner_id</code>，向 <code>compute_path_to_pose</code> Action Server 发送 Goal。当前 Action 的输入包括 <code>goal</code>、<code>start</code>、<code>planner_id</code> 和 <code>use_start</code>，结果是 <code>nav_msgs/Path</code> 与规划耗时。</p><p>Planner Server 收到 Goal 后，需要完成 Costmap 有效性检查、起点获取、坐标变换、规划器选择、路径生成、路径合法性验证和 Result 发布。源码中的 <code>PlannerServer::computePlan()</code> 就是这一层的任务服务器执行入口。</p><p>Planner Server 对外提供 ROS Action，对内通过 Pluginlib 加载 <code>nav2_core::GlobalPlanner</code>。因此上层看到的是统一的 Path 契约，内部仍可以使用不同的规划器实现。</p><h3 id="_5-3-followpath-把-path-变成速度" tabindex="-1">5.3 FollowPath 把 Path 变成速度 <a class="header-anchor" href="#_5-3-followpath-把-path-变成速度" aria-label="Permalink to &quot;5.3 FollowPath 把 Path 变成速度&quot;">​</a></h3><p>规划成功后，Path 被写回 Behavior Tree Blackboard，<code>FollowPath</code> 节点读取 Path，并发送包含 <code>path</code>、<code>controller_id</code> 和 <code>goal_checker_id</code> 的 Action Goal。</p><p>Controller Server 收到 Goal 后选择控制器和目标检查器，保存全局 Path，进入控制周期。每个周期获取机器人 Pose、里程计和局部 Costmap，调用当前 Controller 的 <code>computeVelocityCommands()</code>，再把结果发布为速度指令。</p><p>这条链路的接口责任非常清楚：</p><table tabindex="0"><thead><tr><th>层级</th><th>主要输入</th><th>主要输出</th><th>责任</th></tr></thead><tbody><tr><td><code>bt_navigator</code></td><td>Pose、Behavior Tree</td><td>子 Action Goal</td><td>任务编排</td></tr><tr><td><code>planner_server</code></td><td>起点、终点、Planner ID、Costmap</td><td><code>nav_msgs/Path</code></td><td>全局路径计算</td></tr><tr><td><code>controller_server</code></td><td>Path、Pose、里程计、局部 Costmap</td><td><code>cmd_vel</code></td><td>高频速度计算</td></tr><tr><td>Robot</td><td>速度指令、底盘状态</td><td>里程计、传感器数据</td><td>物理执行与反馈</td></tr></tbody></table><h3 id="_5-4-feedback、result、cancel-和-recovery-返回上层" tabindex="-1">5.4 Feedback、Result、Cancel 和 Recovery 返回上层 <a class="header-anchor" href="#_5-4-feedback、result、cancel-和-recovery-返回上层" aria-label="Permalink to &quot;5.4 Feedback、Result、Cancel 和 Recovery 返回上层&quot;">​</a></h3><p>底层控制器的速度、剩余距离和执行状态可以形成 Feedback，Planner 和 Controller 的成功、失败、取消可以形成 Result，任务管理器据此决定继续、重试还是终止。</p><p>取消方向与数据方向相反。上层取消导航后，Behavior Tree 需要取消当前 Action，Controller Server 需要停止控制循环并发布零速度，Planner Server 则需要终止当前规划请求。</p><p>当前 <code>BtActionNode</code> 的通用实现已经包含异步发送 Goal、等待服务、接收 Result、处理 Feedback 以及在 <code>halt()</code> 中取消 Action 的逻辑。这正是 PDF 所描述的“长时间任务通信边界”的现行演化。</p><p><img src="'+l+`" alt="图 4：当前 Nav2 Action 数据闭环"></p><h2 id="六、2018-设计与当前-nav2-源码如何对应" tabindex="-1">六、2018 设计与当前 Nav2 源码如何对应 <a class="header-anchor" href="#六、2018-设计与当前-nav2-源码如何对应" aria-label="Permalink to &quot;六、2018 设计与当前 Nav2 源码如何对应&quot;">​</a></h2><h3 id="_6-1-missionexecutiontask-演化为-bt-navigator-和上层任务系统" tabindex="-1">6.1 MissionExecutionTask 演化为 BT Navigator 和上层任务系统 <a class="header-anchor" href="#_6-1-missionexecutiontask-演化为-bt-navigator-和上层任务系统" aria-label="Permalink to &quot;6.1 MissionExecutionTask 演化为 BT Navigator 和上层任务系统&quot;">​</a></h3><p>PDF 中的 <code>MissionExecutionTaskServer</code> 是一个明确的高层任务服务器，输入是 <code>MissionPlan</code>。当前 Nav2 核心并没有一个完全同名、覆盖所有业务任务的通用 Mission Execution Server。</p><p>当前更接近的组合是：<code>bt_navigator</code> 负责 NavigateToPose 和 NavigateThroughPoses，Behavior Tree 负责导航内部编排，Waypoint、Route 或外部应用负责更高层任务。充电、开门、乘梯、配送等任务通常仍需要应用层或自定义 BT 节点加入。</p><p>因此，PDF 讨论的是“Nav2 可以成为任务执行引擎”的方向，而当前核心更多提供“导航任务执行器”和可扩展的 BT 入口。</p><h3 id="_6-2-navigatetoposetask-演化为-ros-action-加行为树" tabindex="-1">6.2 NavigateToPoseTask 演化为 ROS Action 加行为树 <a class="header-anchor" href="#_6-2-navigatetoposetask-演化为-ros-action-加行为树" aria-label="Permalink to &quot;6.2 NavigateToPoseTask 演化为 ROS Action 加行为树&quot;">​</a></h3><p>当前 <code>NavigateToPose.action</code> 的 <code>behavior_tree</code> 字段允许每个 Goal 指定行为树文件。<code>NavigateToPoseNavigator::goalReceived()</code> 会读取该字段，加载行为树并初始化目标。</p><p>这与 PDF 中“一个任务可以由不同的任务计划驱动”的思想一致。变化在于，早期设计中任务计划可能是一个更抽象的 <code>MissionPlan</code> 或 Command 消息，当前实现中常见形式是 Behavior Tree XML 加 Blackboard 数据。</p><h3 id="_6-3-computepathtopose-和-followpath-保留了任务边界" tabindex="-1">6.3 ComputePathToPose 和 FollowPath 保留了任务边界 <a class="header-anchor" href="#_6-3-computepathtopose-和-followpath-保留了任务边界" aria-label="Permalink to &quot;6.3 ComputePathToPose 和 FollowPath 保留了任务边界&quot;">​</a></h3><p>当前 Planner Server 和 Controller Server 都以 ROS Action 作为外部接口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BT ComputePathToPose</span></span>
<span class="line"><span>        ↓ Action</span></span>
<span class="line"><span>planner_server</span></span>
<span class="line"><span>        ↓ Pluginlib</span></span>
<span class="line"><span>GlobalPlanner</span></span>
<span class="line"><span></span></span>
<span class="line"><span>BT FollowPath</span></span>
<span class="line"><span>        ↓ Action</span></span>
<span class="line"><span>controller_server</span></span>
<span class="line"><span>        ↓ Pluginlib</span></span>
<span class="line"><span>Controller</span></span></code></pre></div><p>因此，PDF 中“通过语言无关的 ROS Node 和 Action 取代直接 C++ API 调用”的目标，在外部模块边界上已经得到实现。但当前高频算法内部仍使用 C++ Plugin，这是一种工程折中，不应描述成“当前 Nav2 已经完全取消 Plugin”。</p><h3 id="_6-4-environmental-model-以分布式能力部分落地" tabindex="-1">6.4 Environmental Model 以分布式能力部分落地 <a class="header-anchor" href="#_6-4-environmental-model-以分布式能力部分落地" aria-label="Permalink to &quot;6.4 Environmental Model 以分布式能力部分落地&quot;">​</a></h3><p>当前 Nav2 没有一个统一的全局 <code>EnvironmentalModel</code> 节点，把所有地图、感知、预测和语义对象集中到一个服务里。它的能力被分散在 Costmap、TF、Map Server、定位节点、传感器输入、Costmap Filters、Route 和各类 Action／Service 中。</p><p>Costmap 负责构建二维环境代价，StaticLayer 接收 <code>OccupancyGrid</code>，VoxelLayer 用体素保存三维障碍信息，Costmap Filters 负责禁行、限速和优选车道等空间语义。这些都是 PDF 中“环境信息抽象”的部分实现，但还不是一个统一的环境知识接口。</p><h3 id="_6-5-taskserver-是历史草图和测试遗留的交界" tabindex="-1">6.5 TaskServer 是历史草图和测试遗留的交界 <a class="header-anchor" href="#_6-5-taskserver-是历史草图和测试遗留的交界" aria-label="Permalink to &quot;6.5 TaskServer 是历史草图和测试遗留的交界&quot;">​</a></h3><p>PDF 第 13 页的通用 <code>TaskServer&lt;CommandMsg, ResultMsg&gt;</code> 体现了早期设计对异步执行、取消和 Result 设置的关注。当前生产代码主要使用 ROS 2 Action Server、<code>BtActionServer</code>、Planner Server 和 Controller Server。</p><p>当前仓库的 <code>nav2_system_tests/src/dummy_planner</code> 和 <code>dummy_controller</code> 中仍可以检索到 <code>ComputePathToPoseTaskServer</code>、<code>FollowPathTaskServer</code> 和 Command 类型。这些名称说明早期任务接口曾参与系统测试，但它们不应替代对当前生产入口 <code>planner_server</code>、<code>controller_server</code> 和 <code>nav2_msgs/action</code> 的判断。</p><p><img src="`+p+`" alt="图 5：PDF 设计概念与当前 Nav2 对应关系"></p><h2 id="七、这套设计为什么值得保留" tabindex="-1">七、这套设计为什么值得保留 <a class="header-anchor" href="#七、这套设计为什么值得保留" aria-label="Permalink to &quot;七、这套设计为什么值得保留&quot;">​</a></h2><h3 id="_7-1-算法和机器人可以替换" tabindex="-1">7.1 算法和机器人可以替换 <a class="header-anchor" href="#_7-1-算法和机器人可以替换" aria-label="Permalink to &quot;7.1 算法和机器人可以替换&quot;">​</a></h3><p>只要 <code>ComputePathToPose</code> 和 <code>FollowPath</code> 的语义契约稳定，上层就不必关心使用的是 A*、Smac、DWA、RPP、MPPI 还是其他算法。机器人从差速、全向切换到 Ackermann 时，也可以把运动学差异留在规划器、控制器和底盘适配边界内。</p><p>这比把“某个算法类的 C++ 方法”直接暴露给任务层更容易维护，因为替换对象被限制在明确的接口后面。</p><h3 id="_7-2-导航可以和非导航任务组合" tabindex="-1">7.2 导航可以和非导航任务组合 <a class="header-anchor" href="#_7-2-导航可以和非导航任务组合" aria-label="Permalink to &quot;7.2 导航可以和非导航任务组合&quot;">​</a></h3><p>真实机器人任务通常不是“导航到一个 Pose 后结束”，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>取货</span></span>
<span class="line"><span>  → 导航到交付点</span></span>
<span class="line"><span>  → 对接</span></span>
<span class="line"><span>  → 等待工艺完成</span></span>
<span class="line"><span>  → 导航到充电点</span></span>
<span class="line"><span>  → 充电</span></span></code></pre></div><p>如果每个动作都具备 Goal、Feedback、Result、Cancel 和 Failure 语义，就可以把导航、对接、开门、乘梯、充电和工艺等待放进同一套任务编排模型。</p><h3 id="_7-3-恢复行为可复用、可观测" tabindex="-1">7.3 恢复行为可复用、可观测 <a class="header-anchor" href="#_7-3-恢复行为可复用、可观测" aria-label="Permalink to &quot;7.3 恢复行为可复用、可观测&quot;">​</a></h3><p>恢复行为成为 Task 或 Action 后，系统可以清楚记录恢复发生在哪个子任务、执行了多少次、是成功后重试还是最终失败。它也可以被不同导航任务复用，而不必在每个导航函数中重复实现。</p><p>当前默认行为树中的 <code>RecoveryNode</code>、<code>ClearEntireCostmap</code>、<code>Spin</code>、<code>Wait</code> 和 <code>BackUp</code>，就是这种思想的具体体现。</p><h3 id="_7-4-支持多种部署形态" tabindex="-1">7.4 支持多种部署形态 <a class="header-anchor" href="#_7-4-支持多种部署形态" aria-label="Permalink to &quot;7.4 支持多种部署形态&quot;">​</a></h3><p>ROS Node 和 Action 让任务、规划、控制和环境服务能够独立部署，也允许把多个节点组合进同一进程。当前 <code>navigation_launch.py</code> 同时支持独立 Node 和 ComposableNode，说明“分布式边界”和“进程内优化”可以同时存在。</p><h3 id="_7-5-更容易测试和定位故障" tabindex="-1">7.5 更容易测试和定位故障 <a class="header-anchor" href="#_7-5-更容易测试和定位故障" aria-label="Permalink to &quot;7.5 更容易测试和定位故障&quot;">​</a></h3><p>清晰的任务边界让测试可以替换真实规划器和控制器，分别验证任务编排、Action 状态、恢复逻辑和算法结果。出现失败时，也更容易区分：</p><ul><li>Goal 是否被接受。</li><li>Behavior Tree 是否加载成功。</li><li>Planner 是否返回有效 Path。</li><li>Controller 是否生成有效速度。</li><li>Robot 是否真正执行并产生里程计。</li></ul><p><img src="`+c+`" alt="图 6：架构收益与工程边界"></p><h2 id="八、不能忽略的工程边界" tabindex="-1">八、不能忽略的工程边界 <a class="header-anchor" href="#八、不能忽略的工程边界" aria-label="Permalink to &quot;八、不能忽略的工程边界&quot;">​</a></h2><h3 id="_8-1-action-边界会带来通信和状态管理成本" tabindex="-1">8.1 Action 边界会带来通信和状态管理成本 <a class="header-anchor" href="#_8-1-action-边界会带来通信和状态管理成本" aria-label="Permalink to &quot;8.1 Action 边界会带来通信和状态管理成本&quot;">​</a></h3><p>把所有函数都拆成独立 Action 并不一定更好。高频控制循环需要稳定的周期和较低的延迟，当前 Nav2 把 Controller Plugin 留在 <code>controller_server</code> 内部，就是为了避免每个控制周期都跨 ROS 通信边界。</p><p>Action 还会引入 Goal 接受、抢占、取消、超时、Result 顺序和旧回调隔离等状态管理问题。接口越多，系统越需要统一的生命周期和错误语义。</p><h3 id="_8-2-environmental-model-需要时间和坐标一致性" tabindex="-1">8.2 Environmental Model 需要时间和坐标一致性 <a class="header-anchor" href="#_8-2-environmental-model-需要时间和坐标一致性" aria-label="Permalink to &quot;8.2 Environmental Model 需要时间和坐标一致性&quot;">​</a></h3><p>感知、预测、地图和定位信息的更新频率不同，时间戳不同，坐标系也可能不同。如果环境模型只做数据转发而不定义时间、坐标、置信度和冲突处理规则，任务层得到的“统一语义”仍可能是不一致的。</p><p>因此，Environmental Model 的价值不在于把所有数据集中起来，而在于定义任务真正需要的稳定语义和有效性边界。</p><h3 id="_8-3-behavior-tree-需要控制复杂度" tabindex="-1">8.3 Behavior Tree 需要控制复杂度 <a class="header-anchor" href="#_8-3-behavior-tree-需要控制复杂度" aria-label="Permalink to &quot;8.3 Behavior Tree 需要控制复杂度&quot;">​</a></h3><p>Behavior Tree 能表达重试、并行、恢复和动态分支，但树过大后也会变成新的难以维护对象。简单任务仍然应该使用直接逻辑或小型状态机，只有任务关系确实复杂时才引入更大的行为树。</p><h3 id="_8-4-抽象不等于自动获得三维能力" tabindex="-1">8.4 抽象不等于自动获得三维能力 <a class="header-anchor" href="#_8-4-抽象不等于自动获得三维能力" aria-label="Permalink to &quot;8.4 抽象不等于自动获得三维能力&quot;">​</a></h3><p>PDF 把无人机三维导航列为 Stretch Target，说明架构希望保留扩展空间，但三维地图、六自由度运动模型、三维碰撞检查、轨迹优化和飞控接口仍然需要专门实现。把地图字段从二维换成三维，并不能自动得到可飞行路径。</p><h2 id="九、结论-nav2-的核心价值是-可编排的导航能力" tabindex="-1">九、结论：Nav2 的核心价值是“可编排的导航能力” <a class="header-anchor" href="#九、结论-nav2-的核心价值是-可编排的导航能力" aria-label="Permalink to &quot;九、结论：Nav2 的核心价值是“可编排的导航能力”&quot;">​</a></h2><p>这份 PDF 最值得保留的不是某个具体算法，而是下面这条分层关系：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>环境事实</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Environmental Model</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Task Hierarchy</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Behavior Tree / State Machine</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>ROS Action</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Planner / Controller / Recovery</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Robot</span></span></code></pre></div><p>它把导航从“规划器加控制器”提升成了“面向任务的执行框架”：任务层决定做什么，环境模型提供世界知识，Action 提供稳定边界，Behavior Tree 组织复杂行为，Planner 和 Controller 负责具体算法，Robot 完成物理执行。</p><p>当前 Nav2 并没有完全照搬 PDF 中的通用 <code>MissionExecutionTaskServer</code> 和统一 Environmental Model，也没有完全取消内部 C++ Plugin。但 <code>nav2_msgs</code> Action、<code>bt_navigator</code>、Planner／Controller Server、恢复行为树、Costmap Filters 和组合式部署，已经把这份早期设计的主要思想拆开并落到了不同模块中。</p><p>理解这份 PDF 的正确方式，不是把它当作当前代码的类图，而是把它当作 Nav2 设计演化的坐标系：凡是涉及任务组合、算法替换、恢复行为、环境语义和多种部署方式，都可以回到这套“任务契约＋环境抽象”的基本判断上。</p>`,127)])])}const k=e(d,[["render",h]]);export{g as __pageData,k as default};
